create extension if not exists "uuid-ossp";
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.learner_preferences (user_id uuid primary key references public.profiles(id) on delete cascade, education_background text, technical_knowledge text, skills_of_interest text[] not null default '{}', career_goal text, experience_level text, learning_methods text[] not null default '{}', weekly_study_hours numeric check(weekly_study_hours >= 0), desired_outcomes text, target_timeline text, updated_at timestamptz not null default now());
create table if not exists public.learning_paths (id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, summary text, source text not null check(source in ('meta_live','development_mock','manual')), status text not null default 'active' check(status in ('draft','active','archived')), created_at timestamptz not null default now());
create table if not exists public.learning_modules (id uuid primary key default uuid_generate_v4(), learning_path_id uuid not null references public.learning_paths(id) on delete cascade, title text not null, objective text, position int not null check(position > 0), unique(learning_path_id,position));
create table if not exists public.learning_progress (id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, learning_module_id uuid not null references public.learning_modules(id) on delete cascade, status text not null default 'not_started' check(status in ('not_started','in_progress','completed')), updated_at timestamptz not null default now(), unique(user_id,learning_module_id));
create table if not exists public.tutor_conversations (id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, title text, created_at timestamptz not null default now());
create table if not exists public.tutor_messages (id uuid primary key default uuid_generate_v4(), conversation_id uuid not null references public.tutor_conversations(id) on delete cascade, role text not null check(role in ('learner','assistant','system')), content text not null, model_mode text check(model_mode in ('live','mock')), created_at timestamptz not null default now());
create table if not exists public.memory_entries (id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, kind text not null check(kind in ('goal','activity','assessment','competency','gap','project','revision')), content text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.assessment_attempts (id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, topic text not null, score numeric, rubric jsonb not null default '{}', review_required boolean not null default false, created_at timestamptz not null default now());
create index if not exists learning_paths_owner_idx on public.learning_paths(user_id); create index if not exists memory_entries_owner_idx on public.memory_entries(user_id,created_at desc); create index if not exists assessment_attempts_owner_idx on public.assessment_attempts(user_id,created_at desc);
alter table public.profiles enable row level security; alter table public.learner_preferences enable row level security; alter table public.learning_paths enable row level security; alter table public.learning_modules enable row level security; alter table public.learning_progress enable row level security; alter table public.tutor_conversations enable row level security; alter table public.tutor_messages enable row level security; alter table public.memory_entries enable row level security; alter table public.assessment_attempts enable row level security;
create policy "own profile" on public.profiles for all using (auth.uid()=id) with check (auth.uid()=id); create policy "own preferences" on public.learner_preferences for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own paths" on public.learning_paths for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own modules" on public.learning_modules for select using(exists(select 1 from public.learning_paths p where p.id=learning_path_id and p.user_id=auth.uid())); create policy "own progress" on public.learning_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own conversations" on public.tutor_conversations for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own messages" on public.tutor_messages for all using(exists(select 1 from public.tutor_conversations c where c.id=conversation_id and c.user_id=auth.uid())); create policy "own memory" on public.memory_entries for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own attempts" on public.assessment_attempts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
